export interface Video {
  videoId: string;
  title: string;
  description: string;
  publishedAt: string;
  thumbnail: string;
  url: string;
  duration: string;
  viewCount: number;
  likeCount: number;
  tags: string[];
  /** YouTube channel ID. Present once the multi-channel pipeline has run. */
  channelId?: string;
  /** YouTube channel name. Present once the multi-channel pipeline has run. */
  channelTitle?: string;
}

export type IVideo = Video;

/**
 * A YouTube playlist exposed as a browsable collection.
 * Generated by `be/update_videos.py` into `src/collections.json`.
 */
export interface Collection {
  playlistId: string;
  title: string;
  description: string;
  channelId: string;
  channelTitle: string;
  thumbnail: string;
  /** ISO 8601 creation date of the playlist */
  publishedAt: string;
  /** Videos available in src/videos.json, after the pipeline filters */
  videoCount: number;
  /** Raw playlist size reported by the YouTube API */
  itemCount: number;
  /** Video IDs in playlist order; only IDs present in src/videos.json */
  videoIds: string[];
}
